import{_ as t,c as e,o as s,a4 as o}from"./chunks/framework.ttppV29E.js";const i="/assets/viewing-results-1.BcHEzmTh.png",r="data:image/png;base64,",n="/assets/viewing-results-2.DLa9lGJX.png",w=JSON.parse('{"title":"Viewing Test Run Results","description":"","frontmatter":{},"headers":[],"relativePath":"docs/getting-started/viewing-results.md","filePath":"docs/getting-started/viewing-results.md","lastUpdated":1792661575000}'),l={name:"docs/getting-started/viewing-results.md"},a=o('<h1 id="viewing-test-run-results" tabindex="-1">Viewing Test Run Results <a class="header-anchor" href="#viewing-test-run-results" aria-label="Permalink to &quot;Viewing Test Run Results&quot;">​</a></h1><p>After your test run completes, you can inspect the outcome of each test within that run.</p><hr><ol><li><p><strong>Open the Test Run Summary</strong><br> Click on the completed test run entry to open the <strong>Test Run Summary</strong>:</p><p><img src="'+i+'" alt="Viewing Test Results – Step 1"></p></li><li><p><strong>Explore the Summary Panel</strong><br> In the <strong>Test Run Summary</strong>, you can:</p><ol><li><p><strong>Overview</strong><br> See a high-level summary of the entire test run (total tests, pass/fail counts, duration, etc.).</p></li><li><p><strong>Test Results</strong><br> View each test in the run along with its status.</p><ul><li><p>Click a test name to view its logs.</p></li><li><p>If available, download the associated video recording for that test (see <a href="/docs/test-config/test-settings.html"><strong>Test Run Settings</strong></a>).</p></li><li><p>Click <strong>Download results</strong> to download a JUnit XML report of every scenario&#39;s feature, status and logs for this run — useful for importing results into other test-analysis tooling.</p><p><img src="'+r+'" alt="Download results button"></p></li></ul></li><li><p><strong>Log Information</strong><br> Access:</p><ul><li>Logs for every test in the run</li><li>Test Kit logs (the Test Kit sets up the environment before tests execute - you may find these logs helpful for debugging test runs)</li><li>All available video recordings for the run</li><li>AireGlu logs, if the run used AireGlu (see below)</li></ul></li><li><p><strong>AireGlu Logs</strong><br> If your tests invoked AireGlu, the <strong>AireGlu Logs</strong> tab shows what AireGlu itself recorded against the transactions your run used - endpoint invocations, task successes and failures, and their context.</p><p>These logs are read from AireGlu at the moment you open the tab, and are never stored by AireAssert. That means they are subject to AireGlu&#39;s own retention: for an older test run, AireGlu may no longer hold them, and the tab will be empty.</p></li></ol><p><img src="'+n+'" alt="Viewing Test Results – Step 2"></p></li></ol>',4),u=[a];function g(p,A,d,c,h,m){return s(),e("div",null,u)}const S=t(l,[["render",g]]);export{w as __pageData,S as default};
